/// <summary>
/// The service class for the Planner code update batch job.
/// </summary>
class METPlannerCodeUpdService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// The process method of the planner code update batch job
    /// </summary>
    public void processOperation()
    {
        MetItemSiteSettingsSetup metItemSiteSettingsSetup;
        METPlannerCodeAssignmentRules metPlannerCodeAssignmentRules;
        ReqItemTable reqItemTable;
        InventItemGroupItem inventItemGroupItem;
        InventTable inventTable;
        EcoResCategory ecoResCategory;
        EcoResProductCategory ecoResProductCategory;
        EcoResCategoryHierarchy ecoResCategoryHierarchy;
        InventDim inventDim;
        METReqItemTable metreqItemTable;
       
        RecId bestMatch;
        int weight;
        int maxWeight;
        Map map = new Map(Types::Int64, Types::Integer);
        MapEnumerator mapEnumerator;
        
        while select * from metItemSiteSettingsSetup
            order by ItemId
        outer join VendId, RecId from reqItemTable
            where reqItemTable.ItemId == metItemSiteSettingsSetup.ItemId
        outer join forupdate metReqItemTable
            where metReqItemTable.RefRecId == reqItemTable.RecId
        outer join ItemId, ItemGroupId from inventItemGroupItem
            where inventItemGroupItem.ItemId == metItemSiteSettingsSetup.ItemId
        outer join RecId, Product from inventTable
            where inventTable.ItemId == metItemSiteSettingsSetup.ItemId
        outer join Product, Category, CategoryHierarchy from ecoResProductCategory
            where ecoResProductCategory.Product == inventTable.Product
        outer join InventDimId, InventLocationId, InventSiteId from inventDim 
            where inventDim.inventDimId == reqItemTable.CovInventDimId
        {
            map = new Map(Types::Int64, Types::Integer);
               
            while select * from metPlannerCodeAssignmentRules
                where metPlannerCodeAssignmentRules.RuleSubSource == metReqItemTable.SubSource
                    && metPlannerCodeAssignmentRules.RuleEnabled == NoYes::Yes
                
            {
                weight = 0;

                if (metPlannerCodeAssignmentRules.RuleItemGroup == inventItemGroupItem.ItemGroupId)
                {
                    weight += 1;
                }

                if (metPlannerCodeAssignmentRules.RuleVendorSite == metItemSiteSettingsSetup.InventSiteId)
                {
                    weight += 1;
                }

                if (metPlannerCodeAssignmentRules.RuleProductCategory == ecoResProductCategory.Category)
                {
                    weight += 1;
                }
                    
                if (metPlannerCodeAssignmentRules.RuleProductCategoryHierarchy == ecoResProductCategory.CategoryHierarchy)
                {
                    weight += 1;
                }

                if (metPlannerCodeAssignmentRules.RuleVendorAccount == reqItemTable.VendId)
                {
                    weight += 1;
                }

                if (metPlannerCodeAssignmentRules.RuleVendorSite == inventDim.InventSiteId)
                {
                    weight += 1;
                }

                if (metPlannerCodeAssignmentRules.RuleVendorWarehouse == inventDim.InventLocationId)
                {
                    weight += 1;
                }

                map.insert(metPlannerCodeAssignmentRules.RecId, weight);
                    
            }

            // Find the best match using assigned weight
            mapEnumerator = map.getEnumerator();
            maxWeight = 0;
            bestMatch = 0;

            while (mapEnumerator.moveNext())
            {
                if (mapEnumerator.currentValue() > maxWeight)
                {
                    maxWeight = mapEnumerator.currentValue();
                    bestMatch = mapEnumerator.currentKey();
                }
            }

            if (bestMatch)
            {
                ttsbegin;

                select firstonly forupdate PlannerCode from metPlannerCodeAssignmentRules
                    where metPlannerCodeAssignmentRules.RecId == bestMatch;
                    
                if (metReqItemTable.RecId)
                {
                    metReqItemTable.reread(); // reread to avoid update error
                    metReqItemTable.Planner = metPlannerCodeAssignmentRules.PlannerCode;
                    metReqItemTable.update();

                    metPlannerCodeAssignmentRules.RuleUsedBatchUpdate = NoYes::Yes;
                    metPlannerCodeAssignmentRules.update();
                }

                ttscommit;
            }
        }
    }
